@Transactional
public ProductDto update(long id, UpdateProductRequest request) {
    Product product = productRepository.findById(id).orElseThrow();
    if (product.getVersion() != request.version()) {
        // người khác đã lưu sau khi client mở form
        throw new ObjectOptimisticLockingFailureException(Product.class, id);
    }
    product.setName(request.name());
    product.setPrice(request.price());
    product.setDescription(request.description());
    return ProductDto.from(product);   // @Version vẫn chặn hai request chạy trùng nhau
}

// Controller: version đi qua header chuẩn ETag / If-Match thay vì body
@GetMapping("/products/{id}")
ResponseEntity<ProductDto> get(@PathVariable long id) {
    ProductDto dto = productService.get(id);
    return ResponseEntity.ok().eTag(Long.toString(dto.version())).body(dto);   // ETag: "3"
}

@PutMapping("/products/{id}")
ResponseEntity<ProductDto> put(@PathVariable long id,
                               @RequestHeader(HttpHeaders.IF_MATCH) String ifMatch,
                               @RequestBody ProductForm form) {
    long seenVersion = Long.parseLong(ifMatch.replace("\"", ""));
    ProductDto dto = productService.update(id, form.withVersion(seenVersion));
    return ResponseEntity.ok().eTag(Long.toString(dto.version())).body(dto);
}

@RestControllerAdvice
class ConflictHandler {
    @ExceptionHandler(OptimisticLockingFailureException.class)
    ProblemDetail onConflict() {   // dùng If-Match thì trả 412 PRECONDITION_FAILED
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT,
            "Sản phẩm đã được người khác cập nhật. Tải lại để xem thay đổi mới nhất.");
    }
}
